import Image from "next/image";
import Link from "next/link";

const GALLERY_IMAGES = [
  "https://images.unsplash.com/photo-1523580494863-6f3031224c94?q=80&w=600&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1509062522246-3755977927d7?q=80&w=600&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1577896851231-70ef18881754?q=80&w=600&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1427504746696-ea5abd71a32f?q=80&w=600&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1503676260728-1c00da094a0b?q=80&w=600&auto=format&fit=crop",
  "https://images.unsplash.com/photo-1560250097-0b93528c311a?q=80&w=600&auto=format&fit=crop",
];

export default function GalleryPreview() {
  return (
    <section className="py-20 bg-white dark:bg-[#020617] border-t border-slate-100 dark:border-white/5 overflow-hidden">
      <div className="container mx-auto px-6 mb-10 flex justify-between items-end">
         <div>
            <h2 className="text-3xl font-black text-slate-900 dark:text-white">Dokumentasi <span className="text-purple-600">Kegiatan</span></h2>
            <p className="text-slate-500 dark:text-slate-400 mt-2">Momen-momen seru yang terekam kamera lensa OSIS.</p>
         </div>
         <Link href="/galeri" className="hidden md:block text-sm font-bold text-blue-600 hover:underline">Lihat Semua Foto →</Link>
      </div>

      <div className="relative w-full overflow-hidden group">
         <div className="absolute left-0 top-0 bottom-0 w-20 z-10 bg-gradient-to-r from-white dark:from-[#020617] to-transparent pointer-events-none" />
         <div className="absolute right-0 top-0 bottom-0 w-20 z-10 bg-gradient-to-l from-white dark:from-[#020617] to-transparent pointer-events-none" />

         <div className="flex gap-4 animate-scroll whitespace-nowrap">
            {[...GALLERY_IMAGES, ...GALLERY_IMAGES].map((src, index) => (
               <div key={index} className="relative w-[300px] h-[200px] flex-shrink-0 rounded-2xl overflow-hidden cursor-pointer hover:opacity-90 transition-opacity">
                  <Image src={src} alt="Gallery" fill className="object-cover" />
               </div>
            ))}
         </div>
      </div>

      <div className="text-center mt-8 md:hidden">
         <Link href="/galeri" className="text-sm font-bold text-blue-600">Lihat Galeri Lengkap</Link>
      </div>
    </section>
  );
}